package app.unifeed.notification;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import java.time.Instant; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService {private final JdbcTemplate jdbc;private final ObjectMapper json;private final SimpMessagingTemplate ws;public NotificationService(JdbcTemplate jdbc,ObjectMapper json,SimpMessagingTemplate ws){this.jdbc=jdbc;this.json=json;this.ws=ws;}
 @Transactional public NotificationDto create(UUID recipient,String type,Map<String,Object> payload){UUID id=UUID.randomUUID();Instant now=Instant.now();try{jdbc.update("INSERT INTO notifications(id,recipient_id,type,payload) VALUES(?,?,?::notification_type,?::jsonb)",id,recipient,type,json.writeValueAsString(payload));}catch(JsonProcessingException ex){throw new IllegalArgumentException("Invalid notification payload",ex);}NotificationDto dto=new NotificationDto(id,type,payload,null,now);ws.convertAndSendToUser(recipient.toString(),"/queue/notifications",dto);return dto;}
 public List<NotificationDto> list(UUID recipient,String filter,int limit){String condition="UNREAD".equalsIgnoreCase(filter)?" AND read_at IS NULL":"";return jdbc.query("SELECT id,type::text,payload,read_at,created_at FROM notifications WHERE recipient_id=? AND deleted_at IS NULL"+condition+" ORDER BY created_at DESC LIMIT ?",(rs,n)->{try{return new NotificationDto((UUID)rs.getObject(1),rs.getString(2),json.readValue(rs.getString(3),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){}),rs.getTimestamp(4)==null?null:rs.getTimestamp(4).toInstant(),rs.getTimestamp(5).toInstant());}catch(JsonProcessingException ex){throw new IllegalStateException(ex);}},recipient,Math.min(Math.max(limit,1),100));}
 @Transactional public void markRead(UUID id,UUID recipient){jdbc.update("UPDATE notifications SET read_at=COALESCE(read_at,now()) WHERE id=? AND recipient_id=? AND deleted_at IS NULL",id,recipient);}
 @Transactional public void markAllRead(UUID recipient){jdbc.update("UPDATE notifications SET read_at=COALESCE(read_at,now()) WHERE recipient_id=? AND deleted_at IS NULL",recipient);}
 public record NotificationDto(UUID id,String type,Map<String,Object> payload,Instant readAt,Instant createdAt){} }
